CREATE OR REPLACE FUNCTION public.admin_delete_account_v307(p_admin_session_token text, p_account_type text, p_account_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
        declare
          v_admin_id text;
            v_rows integer;
            begin
              v_admin_id := private.require_admin_session_v147(p_admin_session_token);

                if p_account_type in ('employee','admin') then
                    if p_account_id = v_admin_id then
                          return jsonb_build_object('ok',false,'error','CANNOT_DELETE_CURRENT_ADMIN');
                              end if;

                                  delete from public.employees
                                      where id::text = p_account_id;

                                        elsif p_account_type = 'customer' then
                                            delete from public.customers
                                                where id::text = p_account_id;

                                                  else
                                                      return jsonb_build_object('ok',false,'error','UNSUPPORTED_ACCOUNT_TYPE');
                                                        end if;

                                                          get diagnostics v_rows = row_count;

                                                            if v_rows = 0 then
                                                                return jsonb_build_object('ok',false,'error','ACCOUNT_NOT_FOUND');
                                                                  end if;

                                                                    return jsonb_build_object('ok',true);
                                                                    end;
                                                                    $function$

CREATE OR REPLACE FUNCTION private.require_customer_review_session(p_session_token text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
  v_customer_id uuid;
begin
  if trim(coalesce(p_session_token, '')) = '' then
    raise exception 'REVIEW_SESSION_REQUIRED';
  end if;

  select s.customer_id
  into v_customer_id
  from public.customer_review_sessions s
  where s.token_hash = digest(p_session_token, 'sha256')
    and s.revoked_at is null
    and s.expires_at > now()
  limit 1;

  if v_customer_id is null then
    raise exception 'REVIEW_SESSION_INVALID';
  end if;

  update public.customer_review_sessions
  set last_seen_at = now()
  where token_hash = digest(p_session_token, 'sha256');

  return v_customer_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.customer_review_login_v132(p_identity text, p_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
  v_customer public.customers%rowtype;
  v_customer_json jsonb;
  v_stored_password text;
  v_password_ok boolean := false;
  v_token text;
  v_expires_at timestamptz := now() + interval '30 days';
  v_identity_normalized text;
  v_identity_hash bytea;
  v_failed_attempts integer;
begin
  if trim(coalesce(p_identity, '')) = ''
     or coalesce(p_password, '') = '' then
    return jsonb_build_object(
      'ok', false,
      'error', 'REVIEW_LOGIN_FIELDS_REQUIRED'
    );
  end if;

  v_identity_normalized := lower(trim(p_identity));
  v_identity_hash := digest(v_identity_normalized, 'sha256');

  perform pg_advisory_xact_lock(
    hashtextextended(encode(v_identity_hash, 'hex'), 132)
  );

  delete from public.customer_review_login_attempts
  where attempted_at < now() - interval '24 hours';

  select count(*)::integer
  into v_failed_attempts
  from public.customer_review_login_attempts a
  where a.identity_hash = v_identity_hash
    and a.attempted_at >= now() - interval '15 minutes';

  if v_failed_attempts >= 5 then
    return jsonb_build_object(
      'ok', false,
      'error', 'REVIEW_LOGIN_RATE_LIMITED',
      'retry_after_seconds', 900
    );
  end if;

  select c.*
  into v_customer
  from public.customers c
  where lower(
          trim(
            coalesce(to_jsonb(c) ->> 'code', '')
          )
        ) = lower(trim(p_identity))
     or trim(
          coalesce(to_jsonb(c) ->> 'phone', '')
        ) = trim(p_identity)
     or lower(
          trim(
            coalesce(to_jsonb(c) ->> 'email', '')
          )
        ) = lower(trim(p_identity))
  limit 1;

  if v_customer.id is null then
    insert into public.customer_review_login_attempts(identity_hash)
    values (v_identity_hash);

    return jsonb_build_object(
      'ok', false,
      'error', 'REVIEW_LOGIN_INVALID'
    );
  end if;

  v_customer_json := to_jsonb(v_customer);
  v_stored_password := coalesce(
    v_customer_json ->> 'password',
    ''
  );

  if v_stored_password = p_password then
    v_password_ok := true;

  elsif v_stored_password ~ '^\$2[aby]\$' then
    begin
      v_password_ok :=
        crypt(p_password, v_stored_password) = v_stored_password;
    exception
      when others then
        v_password_ok := false;
    end;
  end if;

  if not v_password_ok then
    insert into public.customer_review_login_attempts(identity_hash)
    values (v_identity_hash);

    return jsonb_build_object(
      'ok', false,
      'error', 'REVIEW_LOGIN_INVALID'
    );
  end if;

  delete from public.customer_review_login_attempts
  where identity_hash = v_identity_hash;

  delete from public.customer_review_sessions
  where customer_id = v_customer.id
    and (
      expires_at <= now()
      or revoked_at is not null
    );

  v_token := encode(gen_random_bytes(32), 'hex');

  insert into public.customer_review_sessions(
    customer_id,
    token_hash,
    expires_at
  )
  values (
    v_customer.id,
    digest(v_token, 'sha256'),
    v_expires_at
  );

  return jsonb_build_object(
    'ok', true,
    'session_token', v_token,
    'expires_at', v_expires_at,
    'customer', jsonb_build_object(
      'id', v_customer.id,
      'code', v_customer_json ->> 'code',
      'name', v_customer_json ->> 'name'
    )
  );
end;
$function$
